function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function bottleSVG(p){
  const colors={Dama:["#d7a9c0","#f5e6ee"],Caballero:["#2c3e4d","#aab9c5"],Unisex:["#8a704f","#e8d8bf"]};
  const c=colors[p.gender]||colors.Unisex;
  return `<svg viewBox="0 0 320 235" role="img" aria-label="${esc(p.name)}">
    <defs><linearGradient id="g${p.id}" x1="0" x2="1"><stop offset="0" stop-color="${c[0]}"/><stop offset=".5" stop-color="${c[1]}"/><stop offset="1" stop-color="${c[0]}"/></linearGradient></defs>
    <ellipse cx="160" cy="216" rx="72" ry="10" fill="#000" opacity=".10"/>
    <circle cx="160" cy="49" r="18" fill="#fff" opacity=".9"/>
    <rect x="145" y="54" width="30" height="27" rx="4" fill="#17130b"/>
    <rect x="150" y="44" width="20" height="14" rx="3" fill="#c9a227"/>
    <rect x="91" y="76" width="138" height="125" rx="25" fill="url(#g${p.id})" stroke="#8d7440" stroke-width="2"/>
    <rect x="104" y="108" width="112" height="59" rx="8" fill="#fff" opacity=".82"/>
    <text x="160" y="128" text-anchor="middle" font-family="Georgia,serif" font-size="10" fill="#6a5310">PERFUMES</text>
    <text x="160" y="145" text-anchor="middle" font-family="Georgia,serif" font-weight="bold" font-size="14" fill="#2d2410">IMPERIALES</text>
    <text x="160" y="160" text-anchor="middle" font-family="Arial" font-size="9" fill="#6d665b">${esc(p.id)}</text>
  </svg>`;
}
function generalWhatsApp(){
  const msg='Hola, quiero consultar el catálogo de Perfumes Imperiales de Ensueño.';
  window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`,'_blank');
}
function orderWhatsApp(id,name,size,price){
  const msg=`Hola, quiero pedir el perfume ${name} (código ${id}) en presentación de ${size} ml por S/${price}.`;
  window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`,'_blank');
}
function openModal(id){
  const p=products.find(x=>x.id===id); if(!p)return;
  document.getElementById('modalContent').innerHTML=`
    <div class="meta"><span class="gender">${esc(p.gender)}</span><span class="code">${esc(p.id)}</span></div>
    <h2>${esc(p.name)}</h2>
    <p class="modal-description">${esc(p.description || '')}</p>
    <div class="modal-tags">${p.profiles.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>
    <div class="family-line">${esc(p.family)}</div>
    <h3 style="font-family:Georgia,serif;font-size:23px;margin:0 0 4px">Presentaciones</h3>
    <div class="presentation"><span>30 ml</span><b>S/${p.prices["30"]}</b><button class="order-btn" onclick="orderWhatsApp('${p.id}','${p.name.replace("'","\\'")}','30',${p.prices["30"]})">Pedir</button></div>
    <div class="presentation"><span>50 ml</span><b>S/${p.prices["50"]}</b><button class="order-btn" onclick="orderWhatsApp('${p.id}','${p.name.replace("'","\\'")}','50',${p.prices["50"]})">Pedir</button></div>
    <div class="presentation"><span>100 ml</span><b>S/${p.prices["100"]}</b><button class="order-btn" onclick="orderWhatsApp('${p.id}','${p.name.replace("'","\\'")}','100',${p.prices["100"]})">Pedir</button></div>
    <div class="modal-note">Aroma de inspiración olfativa. Los nombres de referencia se utilizan únicamente para identificar la tendencia aromática.</div>`;
  document.getElementById('modalBack').classList.add('show');
  document.body.style.overflow='hidden';
}
function closeModal(){document.getElementById('modalBack').classList.remove('show');document.body.style.overflow='';}
function fillFilters(){
  const profiles=[...new Set(products.flatMap(p=>p.profiles))].sort((a,b)=>a.localeCompare(b,'es'));
  const families=[...new Set(products.map(p=>p.family))].sort((a,b)=>a.localeCompare(b,'es'));
  const occasions=[...new Set(products.flatMap(p=>p.occasion))].sort((a,b)=>a.localeCompare(b,'es'));
  document.getElementById('profile').innerHTML='<option value="">Todos los estilos</option>'+profiles.map(x=>`<option>${esc(x)}</option>`).join('');
  document.getElementById('family').innerHTML='<option value="">Todas las familias</option>'+families.map(x=>`<option>${esc(x)}</option>`).join('');
  document.getElementById('occasion').innerHTML='<option value="">Todas las ocasiones</option>'+occasions.map(x=>`<option>${esc(x)}</option>`).join('');
}
function render(){
  const q=document.getElementById('search').value.toLowerCase().trim();
  const g=document.getElementById('gender').value;
  const prof=document.getElementById('profile').value;
  const family=document.getElementById('family').value;
  const occ=document.getElementById('occasion').value;
  const list=products.filter(p=>
    (!g||p.gender===g)&&(!prof||p.profiles.includes(prof))&&(!family||p.family===family)&&(!occ||p.occasion.includes(occ))&&
    (!q||`${p.name} ${p.id} ${p.notes} ${p.family} ${p.profiles.join(' ')}`.toLowerCase().includes(q))
  );
  document.getElementById('count').textContent=`${list.length} perfume${list.length===1?'':'s'}`;
  const grid=document.getElementById('grid');
  if(!list.length){grid.innerHTML='<div class="empty">No encontramos esa combinación. Prueba con otro filtro.</div>';return;}
  grid.innerHTML=list.map(p=>`
    <article class="card">
      <div class="bottle"><img src="${p.image}" alt="${esc(p.name)}" loading="lazy"></div>
      <div class="body">
        <div class="meta"><span class="gender">${esc(p.gender)}</span><span class="code">${esc(p.id)}</span></div>
        <h2>${esc(p.name)}</h2>
        <div class="tags">${p.profiles.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>
        <div class="family"><b>${esc(p.family)}</b></div>
        ${p.notes && p.notes.trim().toLowerCase()!==p.name.trim().toLowerCase() ? `<div class="notes">${esc(p.notes)}</div>` : ``}
        <div class="price-main"><strong>S/${p.prices["50"]}</strong><span>50 ml</span></div>
        <button class="view-btn" onclick="openModal('${p.id}')">VER PERFUME ›</button>
      </div>
    </article>`).join('');
}
fillFilters();render();
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});